{
  "predictors": [
    {
      "name": "Customer Satisfaction Index",
      "construction": "Use third-party customer satisfaction survey data, average the past 12 months.",
      "rationale": "High customer satisfaction may lead to repeat business and stronger competitive advantage.",
      "higher_returns_for": "high values of the measure"
    },
    {
      "name": "Internet Traffic",
      "construction": "Use third-party internet traffic data, normalize it by the firm's market capitalization, average the past 12 months.",
      "rationale": "Web traffic can be a measure of the firm's popularity and brand strength.",
      "higher_returns_for": "high values of the measure"
    },
    {
      "name": "CEO Age",
      "construction": "Use CEO age from public filings.",
      "rationale": "Younger CEOs might lead to innovative, high-growth strategies.",
      "higher_returns_for": "low values of the measure"
    },
    {
      "name": "Executive Compensation Ratio",
      "construction": "Calculate the ratio of total executive compensation to total employee compensation, using data from public filings.",
      "rationale": "High executive pay relative to employees might signal agency problems, leading to lower firm value.",
      "higher_returns_for": "low values of the measure"
    },
    {
      "name": "R&D Intensity",
      "construction": "Calculate R&D expense divided by total assets, using data from public filings.",
      "rationale": "High R&D intensity may signal future growth opportunities.",
      "higher_returns_for": "high values of the measure"
    },
    {
      "name": "Social Media Sentiment",
      "construction": "Use a natural language processing model to score the sentiment of social media posts about the firm, average the past 12 months.",
      "rationale": "Positive sentiment might indicate strong customer relationships and predict future business success.",
      "higher_returns_for": "high values of the measure"
    },
    {
      "name": "Supplier Diversity",
      "construction": "Use data from public filings to calculate the diversity of a company's suppliers, e.g. geographical distribution, industry distribution.",
      "rationale": "Firms with diverse suppliers might be better able to manage supply chain risks.",
      "higher_returns_for": "high values of the measure"
    },
    {
      "name": "Employee Turnover Ratio",
      "construction": "Calculate the ratio of the number of departing employees to the total number of employees, using data from public filings.",
      "rationale": "High employee turnover might indicate internal problems and lead to lower productivity.",
      "higher_returns_for": "low values of the measure"
    },
    {
      "name": "Cybersecurity Investment",
      "construction": "Estimate the firm's expenditure on cybersecurity, e.g., from disclosures in public filings.",
      "rationale": "Heavy investment in cybersecurity might predict lower risk of damaging breaches.",
      "higher_returns_for": "high values of the measure"
    },
    {
      "name": "Environmental Responsibility Score",
      "construction": "Use third-party environmental impact scores, average the past 12 months.",
      "rationale": "High environmental responsibility might predict customer loyalty and regulatory support.",
      "higher_returns_for": "high values of the measure"
    }
  ]
}
